import sys
from astropy.utils.misc import InheritDocstrings

def _property_with_doc(doc, return_value):

    def fget(self):
        return return_value
    fget.__doc__ = doc
    return property(fget)

def _property_without_doc(return_value):

    def fget(self):
        return return_value
    fget.__doc__ = None
    return property(fget)

def make_classes(base_doc, ret_value):
    class Base(metaclass=InheritDocstrings):
        bar = _property_with_doc(base_doc, 'base')

    class Subclass(Base):
        bar = _property_without_doc(ret_value)
    return (Base, Subclass)

def check_inheritance(base_doc, ret_value):
    Base, Subclass = make_classes(base_doc, ret_value)
    assert Base.bar.__doc__ == base_doc, 'Base property docstring was not set as expected'
    assert Subclass().bar == ret_value
    assert Subclass.bar.__doc__ == base_doc, 'Property docstring was not inherited by InheritDocstrings. Expected {!r} but got {!r}'.format(base_doc, Subclass.bar.__doc__)

def main():
    try:
        for base_doc in ['BAR', 'x', 'docstring', 'a' * 10]:
            for ret_value in [-1, 0, 1, 42]:
                check_inheritance(base_doc, ret_value)
    except AssertionError as e:

        None
        raise
    return 0
main()

"""
Reproducer for: astropy.units.quantity_input fails when a function (e.g. __init__)
has return annotation -> None, because the decorator attempts `return_.to(None)`.

This script is designed to:
- Exit with code 0 when fixed
- Raise AssertionError (and print a clear stack trace) when the bug is present
- Avoid failures due to incompatible Hypothesis versions / environments

It uses Hypothesis if available and compatible; otherwise it falls back to a small
randomized loop (still property-based in spirit) so the reproducer remains runnable.
"""
import sys
import random
import astropy.units as u

def func_c03d1291(voltage_quantity):

    class PoC:

        @u.quantity_input
        def __init__(self, voltage: u.V) -> None:
            pass
    try:
        obj = PoC(voltage_quantity)
        assert obj is not None
    except AttributeError as e:
        raise
    except Exception as e:
        return

def func_1864aa06():
    for _ in range(50):
        magnitude = random.uniform(-1000000.0, 1000000.0)
        func_c03d1291(magnitude * u.V)
func_1864aa06()

