"""
Reproducer for: "Make validators include the provided value in ValidationError"

The issue: many built-in validators raise ValidationError without params={'value': value},
so overriding error messages with '%(value)s' fails (KeyError) or can't interpolate the value.

This script uses Hypothesis to generate invalid inputs for a variety of *built-in validators*
and asserts that the resulting ValidationError includes a 'value' param equal to the input.

Behavior:
- On buggy Django: raises AssertionError (and prints stack trace).
- On fixed Django: exits 0.
"""
import os
from hypothesis import given, strategies as st, settings, HealthCheck
import django
from django.conf import settings as dj_settings
from django.core import validators
from django.core.exceptions import ValidationError
from django.core.files.uploadedfile import SimpleUploadedFile

def func_e5833e9b():
    os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'reproducer_settings')
    if not dj_settings.configured:
        dj_settings.configure(SECRET_KEY='reproducer', INSTALLED_APPS=[], USE_I18N=False)
    django.setup()

def func_456fbb09(validator, value, label: str):
    try:
        validator(value)
    except ValidationError as e:
        params = getattr(e, 'params', None)
        if not isinstance(params, dict) or 'value' not in params:
            raise AssertionError(f"ValidationError from {label} missing params['value']; params={params!r}, input={value!r}")
        got = params['value']
        same = got is value or got == value or repr(got) == repr(value)
        if not same:
            raise AssertionError(f"ValidationError from {label} has wrong params['value']; expected {value!r}, got {got!r}")
        return
    except Exception as e:
        return

def func_479c1083(kind: str, payload):
    if kind == 'integer_validator':
        return (validators.validate_integer, '-42.5', "validate_integer('-42.5')")
    if kind == 'email_missing_at':
        return (validators.validate_email, 'a', "validate_email('a')")
    if kind == 'email_newline':
        return (validators.validate_email, 'a@b\n.com', "validate_email('a@b\\n.com')")
    if kind == 'slug_unicode_space':
        return (validators.validate_slug, '你 好', "validate_slug('你 好')")
    if kind == 'ipv4_bad_octet':
        b1, b2, b3 = payload
        return (validators.validate_ipv4_address, '256.%d.%d.%d' % (b1, b2, b3), "validate_ipv4_address('256.x.x.x')")
    if kind == 'ipv6_short':
        return (validators.validate_ipv6_address, '1:2', "validate_ipv6_address('1:2')")
    if kind == 'ipv46_bad':
        b1, b2, b3 = payload
        return (validators.validate_ipv46_address, '256.%d.%d.%d' % (b1, b2, b3), "validate_ipv46_address('256.x.x.x')")
    if kind == 'comma_int_list':
        return (validators.validate_comma_separated_integer_list, 'a,b,c', "validate_comma_separated_integer_list('a,b,c')")
    if kind == 'int_list_negative':
        return (validators.int_list_validator(), '-1,2,3', "int_list_validator()('-1,2,3')")
    if kind == 'url_no_scheme':
        return (validators.URLValidator(), 'no_scheme', "URLValidator()('no_scheme')")
    if kind == 'url_bad_ipv6_url':
        return (validators.URLValidator(), 'http://[::1:2::3]/', "URLValidator()('http://[::1:2::3]/')")
    if kind == 'null_character':
        return (validators.ProhibitNullCharactersValidator(), 'a\x00b', "ProhibitNullCharactersValidator()('a\\0b')")
    if kind == 'file_ext':
        v = validators.validate_image_file_extension
        f = SimpleUploadedFile('myfile.txt', b'abc')
        return (v, f, "validate_image_file_extension(SimpleUploadedFile('myfile.txt'))")
    raise AssertionError('Unknown kind %r' % (kind,))

@settings(max_examples=300, suppress_health_check=[HealthCheck.too_slow], deadline=None)
@given(kind=st.sampled_from(['integer_validator', 'email_missing_at', 'email_newline', 'slug_unicode_space', 'ipv4_bad_octet', 'ipv6_short', 'ipv46_bad', 'comma_int_list', 'int_list_negative', 'url_no_scheme', 'url_bad_ipv6_url', 'null_character', 'file_ext']), b1=st.integers(min_value=0, max_value=255), b2=st.integers(min_value=0, max_value=255), b3=st.integers(min_value=0, max_value=255))
def test_ba22db38(kind, b1, b2, b3):
    validator, value, label = func_479c1083(kind, (b1, b2, b3))
    func_456fbb09(validator, value, label=label)
func_e5833e9b()
test_ba22db38()

