    tf = tempfile.NamedTemporaryFile(delete=False)
    try:
        tf.write(b'data')
        tf.flush()
        tf.close()
        with ExitStack() as stack:
            f1 = stack.enter_context(open(tf.name, 'r+b'))
            f2 = stack.enter_context(open(tf.name, 'r+b'))
