"""
Reproduce Django bug: MigrationWriter import ordering violates Django/isort style.

Buggy output example:
    import datetime
    from django.db import migrations, models
    import time

Expected:
    import datetime
    import time
    from django.db import migrations, models

This script configures minimal Django settings (required because MigrationWriter
uses django.utils.timezone.now() for the header timestamp), then uses Hypothesis
to generate migrations that require both:
- stdlib plain imports (e.g. import time / import datetime)
- "from django.db import migrations, models"

It asserts that within the import block, all `import ...` lines come before any
`from ... import ...` lines. When the issue is present, it raises AssertionError
(and prints a clear stack trace). When fixed, it exits 0.
"""
from __future__ import annotations
from hypothesis import HealthCheck, given, settings, strategies as st

def func_5a647abf():
    from django.conf import settings as dj_settings
    if not dj_settings.configured:
