def func_a24b353f(migration_text: str) -> list[str]:
    lines = migration_text.splitlines()
    start = None
    for i, ln in enumerate(lines):
        if ln.startswith('import ') or ln.startswith('from '):
            start = i
            break
    if start is None:
        return []
    block = []
    for ln in lines[start:]:
        if ln.startswith('import ') or ln.startswith('from '):
            block.append(ln)
        else:
            break
    return block

