    import time
    import datetime
    from django.db import migrations, models
    fields = [('id', models.AutoField(primary_key=True, serialize=False)), ('name', models.CharField(max_length=10, default='x'))]
    if use_time:
        fields.append(('myfield_time', models.FloatField(default=time.time)))
    if use_datetime:
        fields.append(('myfield_dt', models.DateTimeField(default=datetime.datetime.now)))
