def print_relevant_backend_note():
    """
    The reported bug is about the fallback XOR emulation on backends lacking native XOR
    (e.g. PostgreSQL). If a backend has native XOR / behaves differently, the test may
    not reproduce; in that case, it should pass.
    """
    return connection.vendor

def build_nary_xor_q(conditions):
    """
    conditions: iterable of Q objects, length >= 3.
    Build left-associative XOR: ((c1 ^ c2) ^ c3) ^ ...
    """
    it = iter(conditions)
    q = next(it)
    for c in it:
        q = q ^ c
    return q
