@hypo_settings(deadline=None, max_examples=200)
@given(data=books_dataset())
def test_aggregate_over_window_requires_subquery_wrapping(data):
    """
    Reproduces: psycopg2.errors.GroupingError: aggregate function calls cannot contain window function calls

    Trigger pattern:
      qs.annotate(win=Window(Avg(... OVER ...)))
      qs.aggregate(Sum('win'))

    On PostgreSQL, this requires Django to introduce a subquery so that the outer
    aggregate sums a materialized column rather than embedding OVER inside SUM().
    """
    if not supports_over_clause():
        return
    Book.objects.all().delete()
    Book.objects.bulk_create([Book(publisher=p, pages=pg) for p, pg in data])
    qs = Book.objects.annotate(avg_publisher_pages=Coalesce(Window(Avg('pages'), partition_by=F('publisher')), 0.0))
    try:
        qs.aggregate(sum_avg_publisher_pages=Sum('avg_publisher_pages'))
    except Exception as e:
        if 'OperationalError' in str(type(e)):
            raise
if __name__ == '__main__':
    test_aggregate_over_window_requires_subquery_wrapping()

