warnings.filterwarnings('ignore', category=DeprecationWarning)
from hypothesis import given, settings, strategies as st, assume
from sympy.combinatorics.permutations import Permutation

def expected_from_cycles_left_to_right(cycles):
    """
    Compute expected result by explicitly applying the cycle mappings to each x.

    For cycles applied left-to-right, the resulting function is:
        f = f_last ∘ ... ∘ f_1 ∘ f_0
    so to evaluate y = f(x), we update x by each cycle in order.

    Return a SymPy Permutation in array form of length n=max_point+1.
    """
    pts = [p for cyc in cycles for p in cyc]
    n = max(pts) + 1 if pts else 0

    def apply_one_cycle(x, cyc):
        k = len(cyc)
        try:
            i = cyc.index(x)
        except ValueError:
            return x
        return cyc[(i + 1) % k]
    arr = []
    for x in range(n):
        y = x
        for cyc in cycles:
            y = apply_one_cycle(y, cyc)
        arr.append(y)
    return Permutation(arr)

@settings(deadline=None, max_examples=500)
@given(a=st.integers(min_value=0, max_value=25), b=st.integers(min_value=0, max_value=25), c=st.integers(min_value=0, max_value=25))
def test_permutation_constructor_allows_nondisjoint_cycles(a, b, c):
    assume(a != b and a != c and (b != c))
    cycles = [[a, b], [a, c]]
    expected = expected_from_cycles_left_to_right(cycles)
    try:
        got = Permutation(cycles)
    except ValueError as e:
        raise
    except Exception as e:
        return
test_permutation_constructor_allows_nondisjoint_cycles()

