from sympy.combinatorics.permutations import Permutation

class CustomPermutation(Permutation):

    def __call__(self, *i):
        try:
            return super(CustomPermutation, self).__call__(*i)
        except TypeError:
            pass
        try:
            perm_obj = i[0]
            return [self._array_form[j] for j in perm_obj]
        except Exception:
            raise TypeError('unrecognized argument')

    def __eq__(self, other):
        if isinstance(other, Permutation):
            return self._hashable_content() == other._hashable_content()
        return super(CustomPermutation, self).__eq__(other)

    def __hash__(self):
        return super(CustomPermutation, self).__hash__()

@settings(deadline=None, max_examples=200)
@given(n=integers(min_value=2, max_value=50))
def test_permutation_subclass_is_preserved(n: int):
    """
    Reproduces sympy issue: Permutation can't be subclassed properly.

    Symptom (buggy behavior): operations/constructors return base Permutation
    even when called on a subclass, e.g. type(p*q) is Permutation instead of
    CustomPermutation.
    """
    assume(n >= 2)
    aform = list(range(1, n)) + [0]
    p = CustomPermutation(aform)
    q = Permutation(aform)
    assert isinstance(p, CustomPermutation), 'Subclass constructor did not return subclass instance'
    r = p * q
    assert type(r) is CustomPermutation, f'Permutation subclass not preserved under multiplication: type(CustomPermutation(...)*Permutation(...)) == {type(r)}'
test_permutation_subclass_is_preserved()

