def func_e7726011(count, shapes):
    symbols = []
    for i in range(count):
        r, c = shapes[i]
        name = f'x{i}'
        symbols.append(MatrixSymbol(name, r, c))
    return symbols

def func_2f4fd6c1(c_source: str, func_name: str, arg_symbols):
    signature_pattern = re.compile(f'^\\s*\\w+\\s+{re.escape(func_name)}\\s*\\((.*?)\\)\\s*\\{{', re.MULTILINE | re.DOTALL)
    m = signature_pattern.search(c_source)
    if not m:
        raise AssertionError(f'Could not locate function signature for {func_name} in generated C source.\n--- C source ---\n{c_source}')
    signature_args_str = m.group(1)
    for sym in arg_symbols:
        name = str(sym)
        ptr_pat = re.compile(f'(?:const\\s+)?double\\s*\\*\\s*{re.escape(name)}\\b')
        if not ptr_pat.search(signature_args_str):
            arr_pat = re.compile(f'(?:const\\s+)?double\\s+{re.escape(name)}\\s*(\\[\\s*\\]|\\[\\s*\\d+\\s*\\])')
            if not arr_pat.search(signature_args_str):
                raise AssertionError(f"Array argument '{name}' was not emitted as a pointer in function signature.\nExpected something like 'double *{name}' in the parameter list.\n--- Signature parameters ---\n{signature_args_str}\n--- Full C source ---\n{c_source}")

@settings(deadline=None, max_examples=100)
