import sys
import sympy as sp
from hypothesis import given, settings, strategies as st, example
from sympy.physics.hep.gamma_matrices import GammaMatrix as G, kahane_simplify, LorentzIndex
from sympy.tensor.tensor import tensor_indices

def func_d44f5d97(n_free: int):
    names = [f'f{i}' for i in range(n_free)] + ['mu']
    idxs = tensor_indices(', '.join(names), LorentzIndex)
    free = list(idxs[:-1])
    mu = idxs[-1]
    return (free, mu)

def func_3c9784c8(indices):
    expr = sp.S.One
    for idx in indices:
        expr = expr * G(idx)
    return expr

@settings(deadline=None, max_examples=100)
@example(length=2, pair_order='updown', placement='suffix')
@given(length=st.integers(min_value=2, max_value=6), pair_order=st.sampled_from(['updown', 'downup']), placement=st.sampled_from(['prefix', 'suffix']))
def test_83c9109f(length, pair_order, placement):
    free_idxs, mu = func_d44f5d97(length)
    A = func_3c9784c8(free_idxs)
    pair = G(mu) * G(-mu) if pair_order == 'updown' else G(-mu) * G(mu)
    expr = pair * A if placement == 'prefix' else A * pair
    result = kahane_simplify(expr)
    expected = 4 * A
    if not result.equals(expected):
        msg = f'kahane_simplify changed the order of leading gamma matrices.\nlength={length}, pair_order={pair_order}, placement={placement}\nExpression: {expr}\nResult:     {result}\nExpected:   {expected}\n'
        raise AssertionError(msg)
