import sys
from sympy import Rational
from hypothesis import given, settings, example, Phase
from hypothesis.strategies import integers, sampled_from, composite, one_of, just

@composite
def func_ab0e8e45(draw, allow_zero=True):
    n = draw(integers(min_value=-64, max_value=64))
    if not allow_zero:
        n = draw(one_of(integers(min_value=-64, max_value=-1), integers(min_value=1, max_value=64)))
    k = draw(integers(min_value=0, max_value=8))
    return float(n / 2 ** k)

@composite
def func_1aa3a049(draw, allow_zero=True):
    rep_type = draw(sampled_from(['str', 'str', 'float', 'int']))
    if rep_type == 'int':
        if allow_zero:
            v = draw(integers(min_value=-50, max_value=50))
        else:
            v = draw(one_of(integers(min_value=-50, max_value=-1), integers(min_value=1, max_value=50)))
        return v
    elif rep_type == 'float':
        return draw(func_ab0e8e45(allow_zero=allow_zero))
    else:
        underlying = draw(sampled_from(['int', 'float']))
        if underlying == 'int':
            if allow_zero:
                v = draw(integers(min_value=-50, max_value=50))
            else:
                v = draw(one_of(integers(min_value=-50, max_value=-1), integers(min_value=1, max_value=50)))
            return str(v)
        else:
            v = draw(func_ab0e8e45(allow_zero=allow_zero))
            return str(v)

@composite
def func_106a1355(draw):
    p = draw(func_1aa3a049(allow_zero=True))
    q = draw(func_1aa3a049(allow_zero=False))
    return (p, q)

@settings(deadline=None, max_examples=200, phases=(Phase.explicit, Phase.generate, Phase.shrink))
@given(args=func_106a1355())
@example(args=('0.5', '100'))
def test_0531eeb6(args):
